import fs from 'node:fs';
import path from 'node:path';
export function collect({ root, paths }) {
  return paths.flatMap((p) => [...fs.readFileSync(path.join(root, p), 'utf8').matchAll(/(PLANT|BARE)/g)].map((m) => ({ rule: 'plant', path: p, ...(m[1] === 'BARE' ? { refused: 'a bare plant' } : {}) })));
}
